{
  "lecture": [
    {
      "etiquette": "F01",
      "R1": {
        "valeur": 1,
        "passage": "le bras stratifié couvre au niveau des retenues au moins 1,5 fois plus de composantes rares que le bras à tirages uniformes"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, par strate de masse, à l'étage des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "e-BH inchangé ; le test de mort reçoit la même stratification. Aucune information sur la stratification n'est servie aux proposeurs."
      },
      "R4": {
        "valeur": 1,
        "passage": "donc la garantie E[e] ≤ 1 sous le nul est conservée sans aucune correction"
      },
      "R5": {
        "valeur": 0,
        "motif": "La règle d'allocation des effectifs entre strates reste à écrire, l'effectif égal n'étant donné que comme exemple."
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues sur mondes générés par programme ; quelques heures de calcul local, zéro appel."
      },
      "R7": {
        "valeur": 1,
        "passage": "sur-représentation des strates rares, la loi des issues sachant les traits restant celle du monde"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F02",
      "R1": {
        "valeur": 1,
        "passage": "Bras frontière avec lentille : composantes rares couvertes (retenues) ≥ 2 fois le bras sans lentille sur la somme"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes couvertes par strate de masse, étages brut et retenues ; fausses et copies. Coût : dollars par rôle, jetons, par génération"
      },
      "R3": {
        "valeur": 1,
        "passage": "les réutiliser côté proposeurs ne masque rien de l'archive (rejet établi : aucun masquage) et n'ajoute aucune prime : la variété vient de l'attribution, pas d'un score."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "Avant chaque génération, un programme tire (graine scellée) une permutation des strates publiques et attribue une strate à chaque proposeur"
      },
      "R6": {
        "valeur": 1,
        "passage": "12 mondes × 3 bras × 4 proposeurs × génération(s) ; ordre de quelques dizaines à une centaine de dollars, bras local presque gratuit."
      },
      "R7": {
        "valeur": 1,
        "passage": "Un acteur qui ajoute des modèles de frontière sans partition recouvre le même bassin ; la partition par strates publiques scellée, décorrélée des cartes, est une propriété de la composition"
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F03",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies de profondeur 2 couvertes au sens de l'oracle dans les retenues augmente d'au moins 30 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre total de composantes plantées vraies couvertes dans les retenues, en particulier les composantes conditionnelles de profondeur 2, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "L'ouverture de générations supplémentaires et l'arrêt des appels dépendent des retenues issues du juge, faisant ainsi dépendre la composition effective de ses verdicts."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 1,
        "passage": "Si plus de 80 % des cartes valides de cette première moitié sont déjà dans le nul des lois de l'archive (au sens du seuil epsilon du regroupement des doublons), appeler la seconde moitié des proposeurs"
      },
      "R6": {
        "valeur": 1,
        "passage": "sur processeur seul (zéro dépense nouvelle) en simulant sur les traces des courses passées (comme v67) la règle d'économie de la moitié des proposeurs et la règle d'arrêt lorsque l'archive stagne"
      },
      "R7": {
        "valeur": 0,
        "motif": "La justification suppose que les retenues constituent un déclencheur fiable grâce au contrôle des fausses découvertes, alors que les faits précisent que la garantie ne borne pas celles définies par l'oracle."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F04",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de lois fausses ou copies promues de formes `si_sinon` et `melange` baisse d'au moins 50 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (lue une fois après la course : nombre de composantes plantées vraies couvertes dans les retenues et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 1,
        "passage": "Conserver à l'identique le regroupement des doublons, la moyenne des valeurs e par groupe et la règle de Benjamini et Hochberg sur les valeurs e."
      },
      "R4": {
        "valeur": 1,
        "passage": "garantissant démontrablement une valeur e d'espérance au plus 1 sous ce nul étendu sur les N tirages."
      },
      "R5": {
        "valeur": 0,
        "motif": "Le pas de la descente de gradient exponentielle n'est pas fixé et les intersections d'au plus deux conditions ne définissent pas à elles seules une partition disjointe."
      },
      "R6": {
        "valeur": 1,
        "passage": "sur processeur seul (quelques minutes de calcul local, zéro appel de modèle) en rejouant ce juge modifié sur un banc de métrologie hors ligne"
      },
      "R7": {
        "valeur": 0,
        "motif": "L'élargissement du nul explique le rejet de copies supplémentaires, mais aucune raison ne relie ce rejet à l'augmentation annoncée de la couverture vraie plutôt qu'à une perte de puissance."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F05",
      "R1": {
        "valeur": 1,
        "passage": "le coût en dollars par génération augmente d'au moins 15 % par rapport à la course de référence"
      },
      "R2": {
        "valeur": 1,
        "passage": "coût en dollars par génération, relevé par les relais ; témoin : la même course sans la modification, au même coût"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le reste de l'organisme ne change pas : mêmes proposeurs, même juge, mêmes plafonds, même monde."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 0,
        "motif": "Réduire d'un tiers un ordre ne définit aucune opération exécutable sur la liste des six formes."
      },
      "R6": {
        "valeur": 0,
        "motif": "Un témoin est nommé, mais aucun ordre de grandeur du coût de l'expérience décisive n'est donné."
      },
      "R7": {
        "valeur": 0,
        "motif": "La sensibilité générique des proposeurs à la forme des consignes n'implique pas une augmentation du coût en dollars."
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
